const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=640,H=400,keys=new Set(),player={x:321,y:298,dir:0,step:0},hint=document.querySelector('#hint'),dialog=document.querySelector('#dialog');let night=true,last=0,elapsed=0,open=false;
let seed=237;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}const grass=Array.from({length:1600},()=>({x:rnd()*W,y:rnd()*H,c:rnd(),s:rnd()}));const trees=[{x:50,y:157,s:1.3},{x:112,y:117,s:1.1},{x:173,y:99,s:1},{x:451,y:100,s:1.1},{x:516,y:140,s:1.3},{x:592,y:194,s:1.5},{x:34,y:272,s:1.4},{x:107,y:320,s:1.1},{x:536,y:337,s:1.2},{x:602,y:393,s:1.4},{x:173,y:399,s:1.2},{x:434,y:400,s:1.05}];
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}function poly(p,c){ctx.fillStyle=c;ctx.beginPath();p.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function glow(x,y,r,a){let g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(255,187,74,${a})`);g.addColorStop(.4,`rgba(255,164,53,${a*.35})`);g.addColorStop(1,'rgba(255,160,40,0)');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
function tree(t){let{x,y,s}=t;ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(s,s);ellipse(5,0,23,8,'#102b295c');rect(-5,-37,10,39,'#463d32');rect(-2,-32,3,29,'#6d5841');for(let i=0;i<3;i++){let yy=-30-i*18,ww=31-i*5;poly([[-ww,yy],[0,yy-42],[ww,yy],[ww-8,yy+7],[-ww+5,yy+5]],['#244c43','#2e5c4c','#3c6a52'][i]);poly([[-ww,yy],[0,yy-42],[-7,yy-5]],['#38634e','#49795a','#598161'][i]);rect(-ww+9,yy-2,9,2,'#75926355')}ctx.restore()}
function house(){ellipse(313,211,87,20,'#112a2955');poly([[238,147],[337,147],[337,216],[238,216]],'#a38b60');poly([[337,147],[380,125],[380,192],[337,216]],'#716e51');rect(244,157,86,5,'#b59b6a');rect(244,188,86,3,'#82754f');for(let i=0;i<8;i++)rect(246+i*12,155,1,55,'#6e63423d');poly([[222,151],[280,86],[351,139],[337,155]],'#3b4546');poly([[280,86],[324,65],[391,122],[351,142]],'#566360');for(let i=0;i<7;i++){let y=91+i*8;poly([[280-(i*7),y],[285-i*7,y-1],[345-i*.2,y+47-i*8],[340-i*.2,y+48-i*8]],'#69716a55')}for(let i=0;i<6;i++)poly([[286+i*7,84-i*3],[289+i*7,83-i*3],[353+i*6,135-i*3],[350+i*6,136-i*3]],'#79806d55');rect(344,71,13,31,'#81775f');rect(342,68,17,6,'#aea083');rect(275,172,25,44,'#493f31');rect(279,177,17,38,'#5c5038');rect(292,193,2,3,'#e7c77b');rect(247,170,19,22,'#514c38');rect(249,172,15,17,night?'#f5cc7b':'#9eb9a1');rect(255,172,2,18,'#77603e');rect(249,179,15,2,'#77603e');poly([[348,160],[365,152],[365,173],[348,181]],night?'#d9b772':'#99ac90');rect(273,216,30,5,'#b0a17a');rect(270,221,35,5,'#8a8566');rect(306,195,15,20,'#605b3d');rect(304,192,19,5,'#81744c');rect(310,186,3,8,'#628b58');rect(314,183,3,11,'#7a985e')}
function lamp(){ellipse(391,263,13,5,'#122c2866');rect(388,210,4,53,'#353c32');rect(383,209,15,3,'#505443');rect(384,199,12,11,'#edbd63');rect(387,199,2,11,'#ffe1a1');poly([[381,199],[390,192],[400,199]],'#41473a');rect(383,211,15,3,'#343e32')}
function character(){let{x,y}=player,bob=keys.size?Math.sin(player.step)*1:0;ellipse(x,y+1,8,3,'#112b2977');ctx.save();ctx.translate(Math.round(x),Math.round(y+bob));const stride=Math.sin(player.step)*2;rect(-5,-7,4,7+Math.round(stride),'#333936');rect(2,-7,4,7-Math.round(stride),'#333936');rect(-6,-2+Math.round(stride),5,3,'#433e35');rect(2,-2-Math.round(stride),5,3,'#433e35');rect(-6,-17,12,12,'#c38752');rect(-7,-16,3,8,'#e2aa6d');rect(5,-16,3,8,'#a86a43');rect(-4,-24,9,8,'#edc99b');rect(-5,-26,11,5,'#493c34');rect(-6,-23,3,5,'#554135');if(player.dir!==3){rect(player.dir===1?-4:3,-21,1,2,'#323a32')}rect(-5,-17,10,3,'#d7c58a');rect(-5,-13,6,7,'#6b6550');rect(-6,-12,2,5,'#a79b71');ctx.restore()}
function river(){poly([[0,334],[44,343],[91,366],[138,378],[168,400],[0,400]],'#3c6964');poly([[0,340],[43,349],[87,373],[134,386],[150,400],[0,400]],'#49817a');for(let i=0;i<24;i++){let x=(i*41+elapsed*7)%153,y=353+(i*17)%48;if(x<(y-335)*2)rect(x,y,8+i%9,1,'#8eafa363')}}
function scene(){rect(0,0,W,H,night?'#385748':'#66855b');grass.forEach(g=>{rect(g.x,g.y,g.s>.6?2:1,g.s>.8?3:1,g.c>.6?'#83a36740':'#233f3540')});poly([[276,218],[307,218],[329,253],[357,294],[351,339],[389,400],[298,400],[308,338],[319,296],[293,255]],'#9c916d');poly([[283,226],[301,225],[317,257],[342,297],[331,343],[359,400],[319,400],[321,339],[329,298],[304,254]],'#b0a07a55');grass.slice(0,100).forEach(g=>{if(g.x>290&&g.x<355&&g.y>230)rect(g.x,g.y,3,2,'#d1bf9055')});river();for(let i=0;i<18;i++){let x=187+i*16,y=274+Math.sin(i*2)*11;rect(x,y,3,2,i%3?'#c8b575':'#e6c99a');rect(x+1,y+2,1,3,'#60724c')}const objects=trees.map(t=>({y:t.y,draw:()=>tree(t)}));objects.push({y:222,draw:house},{y:263,draw:lamp},{y:player.y,draw:character});objects.sort((a,b)=>a.y-b.y).forEach(o=>o.draw());if(night){rect(0,0,W,H,'#102e4936');ctx.globalCompositeOperation='screen';glow(256,182,47,.3);glow(390,208,67,.48+Math.sin(elapsed*3)*.025);glow(287,211,28,.12);ctx.globalCompositeOperation='source-over';for(let i=0;i<20;i++){let x=145+(i*71)%365+Math.sin(elapsed*.5+i)*10,y=160+(i*37)%196+Math.cos(elapsed*.6+i)*6;let a=(Math.sin(elapsed*1.7+i)+1)/2;rect(x,y,1,1,`rgba(234,237,149,${a})`);if(a>.8)glow(x,y,5,.15)}}let vignette=ctx.createRadialGradient(320,210,100,320,210,370);vignette.addColorStop(0,'#071c2200');vignette.addColorStop(1,'#071c22b0');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);for(let i=0;i<7;i++){let x=(elapsed*5+i*103)%710-40,y=70+i*47;rect(x,y,1,2,'#dfd3a53d')}}
function blocked(x,y){return x<24||x>616||y<90||y>387||(x>228&&x<384&&y>133&&y<226)||(x<145&&y>340+x*.25)||trees.some(t=>Math.hypot((x-t.x)*.8,y-t.y)<10)}
function nearby(){if(Math.hypot(player.x-287,player.y-233)<34)return 'house';if(Math.hypot(player.x-390,player.y-257)<37)return 'lamp';return null}
function interact(){if(open){dialog.style.display='none';open=false;return}let n=nearby();if(!n)return;dialog.innerHTML=n==='house'?'<strong>守林人的小屋</strong>門邊留著一張字條：「旅人，天黑了就歇一會吧。森林會替你守住今晚的寧靜。」<br><small>按 E 關閉</small>':'<strong>林間的燈火</strong>暖光在樹影間輕輕搖晃。你找到了一盞為晚歸旅人點亮的燈。<br><small>按 E 關閉</small>';dialog.style.display='block';open=true}
function frame(t){const dt=Math.min((t-last)/1000||0,.04);last=t;elapsed+=dt;let dx=0,dy=0;if(!open && !(typeof heroBusy==='function' && heroBusy())){dx=Number(keys.has('d')||keys.has('ArrowRight'))-Number(keys.has('a')||keys.has('ArrowLeft'));dy=Number(keys.has('s')||keys.has('ArrowDown'))-Number(keys.has('w')||keys.has('ArrowUp'));if(dx||dy){let len=Math.hypot(dx,dy),speed=keys.has('Shift')?100:62,nx=player.x+dx/len*speed*dt,ny=player.y+dy/len*speed*dt;if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny;player.dir=dx<0?1:dx>0?2:dy<0?3:0;player.step+=dt*12}}hint.textContent=open?'按 E 繼續漫遊':nearby()?'E · '+(nearby()==='house'?'閱讀門邊的字條':'看看這盞燈'):'WASD / 方向鍵移動 · 靠近燈火探索';scene();requestAnimationFrame(frame)}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='e'&&!e.repeat)interact();keys.add(e.key.length===1?e.key.toLowerCase():e.key)});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>keys.clear());document.querySelector('#day').onclick=()=>{night=!night;document.querySelector('#day').textContent=night?'☀ 切換日景':'☾ 切換黃昏';document.querySelector('#time').textContent=night?'☾ 黃昏 · 18:42':'☀ 午後 · 15:20'};document.querySelector('#reset').onclick=()=>{player.x=321;player.y=298;keys.clear();open=false;dialog.style.display='none'};document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys.delete(b.dataset.key)});document.querySelector('#touchE').onclick=interact;requestAnimationFrame(frame);
